schema_ddl:
CREATE TABLE conti_correnti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_conto TEXT NOT NULL UNIQUE,
    titolare TEXT NOT NULL,
    saldo NUMERIC(12,2) NOT NULL CHECK (saldo >= 0)
);

CREATE TABLE transazioni (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    conto_id INT NOT NULL REFERENCES conti_correnti(id),
    importo NUMERIC(12,2) NOT NULL,
    data_transazione TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    tipo_operazione TEXT NOT NULL CHECK (tipo_operazione IN ('BONIFICO', 'ACCREDITO', 'PAGAMENTO', 'PRELIEVO'))
);

CREATE TABLE registri_audit (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    transazione_id INT REFERENCES transazioni(id),
    dettagli TEXT NOT NULL,
    registrato_il TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
